private theorem mkₐ₂_includeLeft_eq_zero {y : H} (hy : y ∈ I.toIdeal) :
    mkₐ₂ I (Algebra.TensorProduct.includeLeft (R := R) (S := R) (A := H) (B := H) y) =
      0

private theorem leSup_le_ker_mkₐ₂ :
    leftTensorIdeal (R := R) (H := H) I.toIdeal ⊔ rightTensorIdeal (R := R) (H := H) I.toIdeal ≤
      RingHom.ker (mkₐ₂ I).toRingHom

private theorem quotientComulAlgHom_comp_mkₐ :
    (quotientComulAlgHom I).comp (Ideal.Quotient.mkₐ R I.toIdeal) =
      (mkₐ₂ I).comp (Bialgebra.comulAlgHom R H)

private theorem quotientCounitAlgHom_comp_mkₐ :
    (quotientCounitAlgHom I).comp (Ideal.Quotient.mkₐ R I.toIdeal) =
      Bialgebra.counitAlgHom R H

private theorem comul_mkL_apply (h : H) :
    (quotientComulAlgHom I).toLinearMap (mkL I h)
      = TensorProduct.map (mkL I) (mkL I) (Coalgebra.comul h)

private theorem comul_comp_mkL :
    (quotientComulAlgHom I).toLinearMap ∘ₗ mkL I
      = TensorProduct.map (mkL I) (mkL I) ∘ₗ Coalgebra.comul

@[simp]
private theorem antipode_comp_mkL :
    quotientAntipodeLinearMap I ∘ₗ mkL I = mkL I ∘ₗ HopfAlgebra.antipode R

private theorem mul'_comp_map_mkL :
    LinearMap.mul' R (H ⧸ I.toIdeal) ∘ₗ TensorProduct.map (mkL I) (mkL I)
      = mkL I ∘ₗ LinearMap.mul' R H

private theorem mul'_map_mkL_apply (x : H ⊗[R] H) :
    LinearMap.mul' R (H ⧸ I.toIdeal) (TensorProduct.map (mkL I) (mkL I) x)
      = mkL I (LinearMap.mul' R H x)

private theorem liftBialgHom_kill (f : H →ₐc[R] K)
    (hf : I.toIdeal ≤ RingHom.ker f.toAlgHom.toRingHom) {h : H} (hh : h ∈ I.toIdeal) :
    (f : H →ₐ[R] K) h = 0

private theorem liftBialgHomAlg_mk (f : H →ₐc[R] K)
    (hf : I.toIdeal ≤ RingHom.ker f.toAlgHom.toRingHom) (h : H) :
    liftBialgHomAlg I f hf (Ideal.Quotient.mkₐ R I.toIdeal h) = f h

private theorem quotientAntipodeAlgHom_comp_mkₐ :
    (quotientAntipodeAlgHom I).comp (Ideal.Quotient.mkₐ R I.toIdeal) =
      (Ideal.Quotient.mkₐ R I.toIdeal).comp (HopfAlgebra.antipodeAlgHom R H)

private theorem counit_eq_zero_sSup (S : Set (HopfIdeal R H)) {x : H}
    (hx : x ∈ ⨆ I : S, (I : HopfIdeal R H).toIdeal) :
    Coalgebra.counit (R := R) x = 0

private theorem antipode_mem_sSup (S : Set (HopfIdeal R H)) {x : H}
    (hx : x ∈ ⨆ I : S, (I : HopfIdeal R H).toIdeal) :
    HopfAlgebra.antipode R x ∈ ⨆ I : S, (I : HopfIdeal R H).toIdeal

private lemma tensor_range_mono {P Q : Submodule R M} (hPQ : P ≤ Q) :
    LinearMap.range (TensorProduct.map P.subtype (LinearMap.id : C →ₗ[R] C)) ≤
      LinearMap.range (TensorProduct.map Q.subtype (LinearMap.id : C →ₗ[R] C))

theorem groupLike_mem_groupLikeSetSpan {s : Set (GroupLike R C)} {g : GroupLike R C}
    (hg : g ∈ s) :
    (g : C) ∈ groupLikeSetSpan (R := R) (C := C) s

private lemma tensorSquare_range_mono {P Q : Submodule R C} (hPQ : P ≤ Q) :
    LinearMap.range (TensorProduct.map P.subtype P.subtype) ≤
      LinearMap.range (TensorProduct.map Q.subtype Q.subtype)

private theorem counit_lTensor_transport_map (e : M ≃ₗ[R] N) (t : M ⊗[R] C) :
    Coalgebra.counit.lTensor N (TensorProduct.map e.toLinearMap LinearMap.id t) =
      TensorProduct.map e.toLinearMap LinearMap.id (Coalgebra.counit.lTensor M t)

theorem matrixCoefficientSubmodule_le {P : Submodule R C}
    (hP : ∀ (φ : M →ₗ[R] R) (m : M), matrixCoefficient (R := R) (C := C) φ m ∈ P) :
    matrixCoefficientSubmodule (R := R) (C := C) (M := M) ≤ P

theorem matrixCoefficientSubalgebra_le {S : Subalgebra R C}
    (hS : ∀ (φ : M →ₗ[R] R) (m : M), matrixCoefficient (R := R) (C := C) φ m ∈ S) :
    matrixCoefficientSubalgebra (R := R) (C := C) (M := M) ≤ S

private theorem counit_lTensor_corestrict_map (f : C →ₗc[R] D) (t : M ⊗[R] C) :
    Coalgebra.counit.lTensor M (TensorProduct.map LinearMap.id f.toLinearMap t) =
      Coalgebra.counit.lTensor M t

@[simp]
private theorem cofreeCoact_tmul (m : M) (c : C) :
    cofreeCoact R C M (m ⊗ₜ c) = (TensorProduct.assoc R M C C).symm (m ⊗ₜ Coalgebra.comul c)

private theorem counit_lTensor_rTensor (g : P →ₗ[R] M) (z : P ⊗[R] C) :
    (Coalgebra.counit (R := R) (A := C)).lTensor M (g.rTensor C z)
      = g.rTensor R ((Coalgebra.counit (R := R) (A := C)).lTensor P z)

private theorem cofree_retract (z : M ⊗[R] C) :
    (TensorProduct.rid R M).toLinearMap.rTensor C
        (((Coalgebra.counit (R := R) (A := C)).lTensor M).rTensor C (cofreeCoact R C M z)) = z

